function countInversions(scores) {
  function sort(a) {
    if (a.length <= 1) return [a, 0]
    const mid = a.length >> 1
    const [left, x] = sort(a.slice(0, mid))
    const [right, y] = sort(a.slice(mid))
    const out = []
    let i = 0
    let j = 0
    let count = x + y
    while (i < left.length && j < right.length) {
      if (left[i] <= right[j]) out.push(left[i++])
      else {
        out.push(right[j++])
        count += left.length - i
      }
    }
    return [out.concat(left.slice(i), right.slice(j)), count]
  }
  return sort([...scores])[1]
}

